def init(sizes, ops):
    k = int(sizes.get('k', sizes.get('d')))
    V = int(sizes['V'])
    A = ops.np.normal((k, k), 1, 1.0)
    B = ops.np.normal((k, V), 2, 1.0)
    params = {'A': A, 'B': B, 'z0': 0}
    return params, {'z': 0}


def update(params, state, token, ops):
    z = int(state['z'])
    x = int(token)
    row = params['A'][z, :]
    col = params['B'][:, x]
    scores = ops.np.multiply(row, col)
    nz = int(ops.np.argmax(scores))
    return {'z': nz}


def predict(params, state, ops):
    z = int(state['z'])
    row = params['A'][z, :]
    scores = ops.np.matmul(row, params['B'])
    return int(ops.np.argmax(scores))

def init(sizes, ops):
    k = int(sizes['k']) if 'k' in sizes else int(sizes['d'])
    V = int(sizes['V'])
    A = ops.np.absolute(ops.np.normal((k, k), 1, 1.0))
    B = ops.np.absolute(ops.np.normal((k, V), 2, 1.0))
    params = {'A': A, 'B': B}
    state = {'z': 0}
    return params, state

def update(params, state, token, ops):
    A = params['A']
    B = params['B']
    z = state['z']
    x = int(token)
    scores = ops.np.multiply(A[z, :], B[:, x])
    znew = int(ops.np.argmax(scores))
    return {'z': znew}

def predict(params, state, ops):
    A = params['A']
    B = params['B']
    z = state['z']
    scores = A[z, :] @ B
    return int(ops.np.argmax(scores))

def init(sizes, ops):
    V = int(sizes['V'])
    text = []
    x = 12345
    for i in range(8 * V * V):
        x = (1103515245 * x + 12345) % 2147483648
        text.append((x // 65536) % V)
    counts = [[[0 for v in range(V)] for b in range(V)] for a in range(V)]
    for i in range(len(text) - 2):
        counts[text[i]][text[i + 1]][text[i + 2]] += 1
    params = {'T': ops.np.array(counts)}
    state = ops.np.array([0, 0])
    return params, state


def update(params, state, token, ops):
    b = int(state[1])
    w = ops.np.array([b, int(token)])
    return w


def predict(params, state, ops):
    a = int(state[0])
    b = int(state[1])
    return int(ops.np.argmax(params['T'][a, b, :]))

def init(sizes, ops):
    V = int(sizes['V'])
    T = ops.np.normal((V, V, V), 0, 1.0)
    params = {'T': T}
    state = ops.np.array([0, 0])
    return params, state


def update(params, state, token, ops):
    state[0] = state[1]
    state[1] = int(token)
    return state


def predict(params, state, ops):
    row = params['T'][int(state[0]), int(state[1])]
    return int(ops.np.argmax(row))
